<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Personal Expense Tracker</title>
  <style>
    * { box-sizing: border-box; }
    body {
      font-family: system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
      max-width: 720px;
      margin: 0 auto;
      padding: 1rem 1.25rem 2rem;
      color: #1a1a1a;
      background: #f6f7f9;
    }
    h1 { font-size: 1.5rem; margin: 0 0 1rem; }
    h2 { font-size: 1.1rem; margin: 1.25rem 0 0.5rem; }
    section {
      background: #fff;
      border: 1px solid #dde1e6;
      border-radius: 8px;
      padding: 1rem;
      margin-bottom: 1rem;
    }
    label {
      display: block;
      font-size: 0.85rem;
      font-weight: 600;
      margin-bottom: 0.25rem;
    }
    .field { margin-bottom: 0.75rem; }
    input[type="number"],
    input[type="date"],
    input[type="text"],
    select {
      width: 100%;
      padding: 0.45rem 0.5rem;
      border: 1px solid #c5ccd6;
      border-radius: 4px;
      font-size: 1rem;
      background: #fff;
    }
    .row {
      display: flex;
      flex-wrap: wrap;
      gap: 0.75rem;
    }
    .row .field { flex: 1 1 140px; }
    button {
      cursor: pointer;
      font-size: 0.95rem;
      padding: 0.5rem 0.9rem;
      border-radius: 4px;
      border: 1px solid #2b5fc5;
      background: #2b5fc5;
      color: #fff;
    }
    button:hover { background: #234ea3; }
    button.exp-del {
      background: #fff;
      color: #b00020;
      border-color: #d4a0a8;
      padding: 0.25rem 0.55rem;
      font-size: 0.85rem;
    }
    button.exp-del:hover { background: #fdecee; }
    #form-error {
      color: #b00020;
      font-size: 0.9rem;
      min-height: 1.25em;
      margin: 0.25rem 0 0.5rem;
    }
    #total-wrap {
      font-size: 1.15rem;
      font-weight: 700;
      margin-bottom: 0.75rem;
    }
    #cat-summary {
      display: flex;
      flex-wrap: wrap;
      gap: 0.5rem;
      margin-bottom: 0.5rem;
    }
    .cat-total {
      background: #eef2f8;
      border: 1px solid #d0d8e4;
      border-radius: 4px;
      padding: 0.35rem 0.6rem;
      font-size: 0.9rem;
    }
    #expense-list {
      list-style: none;
      margin: 0;
      padding: 0;
    }
    .expense {
      display: flex;
      align-items: center;
      gap: 0.75rem;
      padding: 0.6rem 0.25rem;
      border-bottom: 1px solid #e8ebef;
      flex-wrap: wrap;
    }
    .expense:last-child { border-bottom: none; }
    .expense .exp-amount {
      font-weight: 700;
      min-width: 4.5rem;
    }
    .expense .exp-cat {
      background: #eef2f8;
      padding: 0.15rem 0.45rem;
      border-radius: 3px;
      font-size: 0.85rem;
      text-transform: capitalize;
    }
    .expense .exp-date { color: #555; font-size: 0.9rem; }
    .expense .exp-note {
      color: #666;
      font-size: 0.85rem;
      flex: 1 1 auto;
    }
    .expense .exp-del { margin-left: auto; }
    .expense[hidden] { display: none; }
    .empty-msg { color: #777; font-size: 0.95rem; padding: 0.5rem 0; }
  </style>
</head>
<body>
  <h1>Personal Expense Tracker</h1>

  <section aria-label="Add expense">
    <h2>Add expense</h2>
    <form id="expense-form" novalidate>
      <div class="row">
        <div class="field">
          <label for="amount">Amount</label>
          <input type="number" id="amount" step="0.01" min="0" placeholder="0.00" />
        </div>
        <div class="field">
          <label for="category">Category</label>
          <select id="category">
            <option value="groceries">groceries</option>
            <option value="transport">transport</option>
            <option value="bills">bills</option>
            <option value="fun">fun</option>
          </select>
        </div>
        <div class="field">
          <label for="date">Date</label>
          <input type="date" id="date" />
        </div>
      </div>
      <div class="field">
        <label for="note">Note (optional)</label>
        <input type="text" id="note" placeholder="Optional note" />
      </div>
      <div id="form-error" role="alert"></div>
      <button type="submit" id="add-expense">Add expense</button>
    </form>
  </section>

  <section aria-label="Filters">
    <h2>Filters</h2>
    <div class="row">
      <div class="field">
        <label for="filter-category">Category</label>
        <select id="filter-category">
          <option value="all">all</option>
          <option value="groceries">groceries</option>
          <option value="transport">transport</option>
          <option value="bills">bills</option>
          <option value="fun">fun</option>
        </select>
      </div>
      <div class="field">
        <label for="filter-from">From</label>
        <input type="date" id="filter-from" />
      </div>
      <div class="field">
        <label for="filter-to">To</label>
        <input type="date" id="filter-to" />
      </div>
    </div>
  </section>

  <section aria-label="Summary and list">
    <h2>Summary</h2>
    <div id="total-wrap">Total: <span id="total">0.00</span></div>
    <div id="cat-summary"></div>

    <h2>Expenses</h2>
    <ul id="expense-list"></ul>
  </section>

  <script>
    (function () {
      const STORAGE_KEY = 'expense-tracker-items';
      const CATEGORIES = ['groceries', 'transport', 'bills', 'fun'];

      const form = document.getElementById('expense-form');
      const amountInput = document.getElementById('amount');
      const categoryInput = document.getElementById('category');
      const dateInput = document.getElementById('date');
      const noteInput = document.getElementById('note');
      const formError = document.getElementById('form-error');
      const listEl = document.getElementById('expense-list');
      const totalEl = document.getElementById('total');
      const catSummaryEl = document.getElementById('cat-summary');
      const filterCategory = document.getElementById('filter-category');
      const filterFrom = document.getElementById('filter-from');
      const filterTo = document.getElementById('filter-to');

      /** @type {{id:string, amount:number, category:string, date:string, note:string}[]} */
      let expenses = loadExpenses();

      function loadExpenses() {
        try {
          const raw = localStorage.getItem(STORAGE_KEY);
          if (!raw) return [];
          const parsed = JSON.parse(raw);
          if (!Array.isArray(parsed)) return [];
          return parsed.filter(function (e) {
            return e && typeof e.id === 'string' && typeof e.amount === 'number' &&
              typeof e.category === 'string' && typeof e.date === 'string';
          });
        } catch (err) {
          return [];
        }
      }

      function saveExpenses() {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(expenses));
      }

      function formatAmount(n) {
        return n.toFixed(2);
      }

      function isVisible(exp) {
        const cat = filterCategory.value;
        if (cat !== 'all' && exp.category !== cat) return false;
        const from = filterFrom.value;
        const to = filterTo.value;
        if (from && exp.date < from) return false;
        if (to && exp.date > to) return false;
        return true;
      }

      function render() {
        listEl.innerHTML = '';
        const sorted = expenses.slice().sort(function (a, b) {
          if (a.date !== b.date) return a.date < b.date ? 1 : -1;
          return a.id < b.id ? 1 : -1;
        });

        let visibleTotal = 0;
        const catTotals = {};
        CATEGORIES.forEach(function (c) { catTotals[c] = 0; });

        let visibleCount = 0;
        sorted.forEach(function (exp) {
          const visible = isVisible(exp);
          const li = document.createElement('li');
          li.className = 'expense';
          li.dataset.id = exp.id;
          if (!visible) li.hidden = true;

          const amt = document.createElement('span');
          amt.className = 'exp-amount';
          amt.textContent = formatAmount(exp.amount);

          const cat = document.createElement('span');
          cat.className = 'exp-cat';
          cat.textContent = exp.category;

          const dt = document.createElement('span');
          dt.className = 'exp-date';
          dt.textContent = exp.date;

          const note = document.createElement('span');
          note.className = 'exp-note';
          note.textContent = exp.note || '';

          const del = document.createElement('button');
          del.type = 'button';
          del.className = 'exp-del';
          del.textContent = 'Delete';
          del.addEventListener('click', function () {
            expenses = expenses.filter(function (e) { return e.id !== exp.id; });
            saveExpenses();
            render();
          });

          li.appendChild(amt);
          li.appendChild(cat);
          li.appendChild(dt);
          li.appendChild(note);
          li.appendChild(del);
          listEl.appendChild(li);

          if (visible) {
            visibleCount++;
            visibleTotal += exp.amount;
            if (catTotals[exp.category] !== undefined) {
              catTotals[exp.category] += exp.amount;
            }
          }
        });

        if (sorted.length === 0) {
          const empty = document.createElement('li');
          empty.className = 'empty-msg';
          empty.textContent = 'No expenses yet.';
          listEl.appendChild(empty);
        }

        totalEl.textContent = formatAmount(visibleTotal);

        catSummaryEl.innerHTML = '';
        CATEGORIES.forEach(function (c) {
          const el = document.createElement('div');
          el.className = 'cat-total';
          el.setAttribute('data-cat', c);
          el.textContent = c + ': ' + formatAmount(catTotals[c]);
          catSummaryEl.appendChild(el);
        });
      }

      form.addEventListener('submit', function (e) {
        e.preventDefault();
        formError.textContent = '';

        const rawAmount = amountInput.value.trim();
        const amount = Number(rawAmount);
        const category = categoryInput.value;
        const date = dateInput.value;
        const note = noteInput.value.trim();

        if (rawAmount === '' || !Number.isFinite(amount) || amount <= 0 || !date) {
          formError.textContent = 'Please enter a valid positive amount and a date.';
          return;
        }

        if (CATEGORIES.indexOf(category) === -1) {
          formError.textContent = 'Please select a valid category.';
          return;
        }

        expenses.push({
          id: String(Date.now()) + '-' + Math.random().toString(36).slice(2, 9),
          amount: Math.round(amount * 100) / 100,
          category: category,
          date: date,
          note: note
        });
        saveExpenses();
        formError.textContent = '';
        amountInput.value = '';
        noteInput.value = '';
        render();
      });

      filterCategory.addEventListener('change', render);
      filterFrom.addEventListener('change', render);
      filterTo.addEventListener('change', render);

      if (!dateInput.value) {
        const today = new Date();
        const yyyy = today.getFullYear();
        const mm = String(today.getMonth() + 1).padStart(2, '0');
        const dd = String(today.getDate()).padStart(2, '0');
        dateInput.value = yyyy + '-' + mm + '-' + dd;
      }

      render();
    })();
  </script>
</body>
</html>
